<section class="result-card panel"><span class="result-icon <?= $passed?'passed':'failed' ?>"><?= $passed?'✓':'!' ?></span><p class="eyebrow"><?= $passed?'ÉVALUATION RÉUSSIE':'À RETENTER' ?></p><h1><?= htmlspecialchars($assessment['title']) ?></h1><strong><?= $score ?>%</strong><p><?= $passed?'Félicitations ! Vous avez atteint le seuil de réussite.':'Votre score est inférieur au seuil de '.$assessment['passing_score'].'%. Révisez la section puis réessayez.' ?></p><div><?php if($passed&&$assessment['type']==='final_exam'): ?><a class="btn primary" href="/mon-compte">Récupérer mon diplôme</a><?php elseif(!$passed): ?><a class="btn primary" href="/academie/composition?id=<?= $assessment['id'] ?>">Réessayer</a><?php endif ?><a class="btn secondary" href="/academie/formation?course=<?= $assessment['course_id'] ?>">Retour au cours</a></div></section><style>.result-card{max-width:600px;margin:50px auto;padding:45px;text-align:center}.result-icon{width:70px;height:70px;border-radius:50%;display:grid;place-items:center;margin:auto;font-size:30px}.result-icon.passed{background:#dff6ea;color:#178457}.result-icon.failed{background:#fde8e3;color:#b54838}.result-card>strong{font:800 54px Manrope;color:var(--primary)}.result-card>p:not(.eyebrow){color:var(--muted)}.result-card>div{display:flex;justify-content:center;gap:10px;margin-top:25px}</style>
